// This code demonstrates a common vulnerability: the use of a hardcoded API key without validation.
// If an attacker intercepts this request, they can potentially read sensitive data.
public class VulnerableAPIUsage {
    public static void main(String[] args) {
        // This is a vulnerable example where the API key is hardcoded.
        // It should be validated against a secure secret key.
        String apiKey = "sk_live_abc123xyz"; // This is vulnerable to interception
        String[] headers = { "Authorization: Bearer " + apiKey };

        // The code below is vulnerable because it does not validate the API key.
        // It should be replaced with a secure validation method.
        System.out.println("Accessing API...");
    }
}
